def get_card_style(cat_name: str) -> dict:
    """Robust style lookup with fallback to default."""
    if not cat_name:
        return DEFAULT_CARD_STYLE
    c_clean = str(cat_name).strip()
    for key, style in CAT_STYLES.items():
        if key.lower() in c_clean.lower() or c_clean.lower() in key.lower():
            return style
    return DEFAULT_CARD_STYLE

# ==========================================
# MATCHING & SANITIZATION HELPERS
# ==========================================
def clean_resource_title(title: str, subject: str = "") -> str:
    """Sanitizes resource titles, removing garbled prefixes, emojis, and duplicate subject text."""
    if not title:
        return "Untitled Resource"
    
    t = str(title).strip()
    t = re.sub(r'^(arro[a-zA-Z0-9_]*|arrow|📌|📖|📝|📋|🎬|🔗|📁)\s*[-:_]*\s*', '', t, flags=re.IGNORECASE)
    t = re.sub(r'^\s*[-:_]+\s*', '', t)
    
    if subject and subject.strip():
        s_clean = str(subject).strip()
        if t.lower().endswith(f"| {s_clean.lower()}"):
            t = t[:-len(s_clean)-2].strip()
        elif t.lower().endswith(s_clean.lower()):
            t = t[:-len(s_clean)].strip()
            
    t = t.strip()
    if not t:
        return f"📌 Resource | {subject}" if subject else "📌 Resource"
        
    return f"📌 {t} | {subject}" if (subject and subject.lower() not in t.lower()) else f"📌 {t}"

def get_clean_str(val) -> str:
    """Sanitizes Supabase string values, handling None and nulls cleanly."""
    if val is None:
        return ""
    s = str(val).strip()
    if s.lower() in ["none", "null", "nan"]:
        return ""
    return s

def is_subject_match(q: dict, target_subject: str) -> bool:
    """Flexible subject matching with clean null handling."""
    if not target_subject:
        return True
    
    q_subj = get_clean_str(q.get("subject")).lower()
    t_subj = get_clean_str(target_subject).lower()
    
    if not q_subj:
        return True
    if q_subj == t_subj:
        return True
    if "paper 1" in q_subj or "general" in q_subj:
        return True
    if t_subj in q_subj or q_subj in t_subj:
        return True
    main_target = t_subj.split("(")[0].strip()
    if main_target and main_target in q_subj:
        return True
    return False

def is_unit_match(q: dict, u_idx: int) -> bool:
    """Robust regex matching for Unit 1 through Unit 10."""
    val_unit = get_clean_str(q.get("unit"))
    val_topic = get_clean_str(q.get("topic"))
    val_unit_num = get_clean_str(q.get("unit_number")) or get_clean_str(q.get("unit_no")) or get_clean_str(q.get("unit_id"))
    
    if val_unit_num == str(u_idx) or val_unit_num == f"0{u_idx}":
        return True

    text = (val_unit + " " + val_topic).strip().lower()
    if not text:
        return False

    u_str = f"unit {u_idx}"
    u_str_dash = f"unit-{u_idx}"
    u_str_nodspace = f"unit{u_idx}"
    u_str_zero = f"unit 0{u_idx}"

    if val_unit.lower() in [u_str, u_str_dash, u_str_nodspace, u_str_zero, str(u_idx)]:
        return True
    if val_topic.lower() in [u_str, u_str_dash, u_str_nodspace, u_str_zero, str(u_idx)]:
        return True

    pattern = rf"\bunit\s*[-:_]*\s*0*{u_idx}\b"
    if re.search(pattern, text, re.IGNORECASE):
        return True
        
    if u_str in text or u_str_dash in text or u_str_nodspace in text or u_str_zero in text:
        return True
        
    return False

def get_option_val(q: dict, opt_key: str) -> str:
    """Extracts option value supporting multiple CSV schema column keys."""
    key = opt_key.lower()
    possible_keys = [
        f"option_{key}", f"option{key}", f"opt_{key}", f"opt{key}", key,
        f"option_{opt_key}", f"option{opt_key}", f"opt_{opt_key}", f"opt{opt_key}", opt_key
    ]
    for k in possible_keys:
        val = q.get(k)
        if val is not None and str(val).strip() != "":
            return str(val).strip()
    return ""

