    st.markdown("---")

    # Single Unified Resource Card Helper (Fully compatible with Python 3.9 - 3.12)
    def render_single_unified_card(item):
        raw_title = item.get("title", "Untitled Resource")
        cat = item.get("category", "General")
        subj = item.get("subject", "General")
        url = item.get("file_url", "")
        
        clean_title_str = clean_resource_title(raw_title, subj)
        style = get_card_style(cat)
        
        card_bg = style["card_bg"]
        border_color = style["border_color"]
        title_color = style["title_color"]
        meta_color = style["meta_color"]
        btn_bg = style["btn_bg"]
        btn_text = style["btn_text"]
        
        link_html = ""
        if url:
            if "youtube" in url or cat == "Video Lectures":
                link_html = f'<div style="margin-top: 12px;"><a href="{url}" target="_blank" style="display: inline-block; background: {btn_bg}; color: {btn_text} !important; font-weight: bold; padding: 10px 22px; border-radius: 8px; text-decoration: none; font-size: 0.95rem;">🎬 Watch Video Lecture ➔</a></div>'
